## Why This Is Asked
This tests DP partitioning with a non-trivial per-segment cost that depends on both sum and min, plus reconstruction.

## Key Concepts
- Partition DP with exact k segments
- Precompute minVal(l,r) in O(n^2)
- Transition uses prefix sums and minVal; reconstruct with parent pointers

## Code Example
```javascript
function maxCost(A, k){
  const n = A.length;
  const pref = new Array(n+1).fill(0);
  for(let i=1;i<=n;i++) pref[i] = pref[i-1] + A[i-1];
  // minVal[l][r]
  const minVal = Array.from({length:n+2}, ()=>Array(n+2).fill(0));
  for(let l=1;l<=n;l++){
    let m = A[l-1];
    minVal[l][l] = m;
    for(let r=l;r<=n;r++){
      m = (r===l) ? A[l-1] : Math.min(m, A[r-1]);
      minVal[l][r] = m;
    }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++){ dp[i][1] = (pref[i]-pref[0]) * minVal[1][i]; par[i][1] = 0; }
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let p=t-1;p<=i-1;p++){
        const val = dp[p][t-1] + (pref[i]-pref[p]) * minVal[p+1][i];
        if(val > dp[i][t]){ dp[i][t] = val; par[i][t] = p; }
      }
    }
  }
  // reconstruction omitted for brevity
  return {best: dp[n][k]};
}
```

## Why This Is Asked
New angle: per-block setup cost while selecting up to k blocks, non-overlapping; tests ability to derive a compact DP with prefix sums and a best-so-far trick; includes reconstruction.

## Key Concepts
- Non-overlapping subarrays with a per-block cost
- Prefix sums to compute block values quickly
- Best-so-far technique to achieve O(nk) time
- Reconstruction pointers for endpoints

## Code Example
```javascript
function maxKBlocksWithCost(A, k, cost) {
  const n = A.length;
  const P = new Array(n+1).fill(0);
  for (let i = 1; i <= n; i++) P[i] = P[i-1] + A[i-1];
  const NEG = -1e15;
  const dp = Array.from({ length: n+1 }, () => new Array(k+1).fill(NEG));
  dp[0][0] = 0;
  const bestVal = new Array(k+1).fill(NEG);
  bestVal[0] = 0; // dp[0][0] - P[0]

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      const candidate = P[i] - cost + bestVal[t-1];
      dp[i][t] = Math.max(dp[i-1][t], candidate);
    }
    // update bestVal for next i
    for (let t = 1; t <= k; t++) {
      const val = dp[i][t-1] - P[i];
      if (val > bestVal[t]) bestVal[t] = val;
    }
  }
  return { dp, P };
}
```

## Why This Problem Is Asked

This problem explores non-overlapping palindromic substring selection using a two-dimensional DP that tracks prefix length and the number of selected substrings. It tests palindrome precomputation, transition logic, and solution reconstruction under constraints.

## Key Concepts

- **Palindrome table**: pal[l][r] indicates whether s[l..r] is a palindrome
- **DP state**: dp[i][t] represents the maximum total length obtainable from prefix s[0..i] using exactly t substrings
- **Transition**: Either skip the current position or end a palindrome at i (starting at some l)
- **Reconstruction**: Use parent pointers to backtrack and retrieve the selected substrings

## Code Example

```javascript
function maxPalindromes(s, k) {
  const n = s.length;
  const pal = Array.from({ length: n }, () => Array(n).fill(false));

  for (let i = 0; i < n; i++) pal[i][i] = true;
  for (let len = 2; len <= n; len++) {
    for (let l = 0; l + len - 1 < n; l++) {
      const r = l + len - 1;
      if (s[l] === s[r] && (len === 2 || pal[l+1][r-1])) {
        pal[l][r] = true;
      }
    }
  }

  const dp = Array.from({ length: n }, () => Array(k+1).fill(0));
  const parent = Array.from({ length: n }, () => Array(k+1).fill(null));

  for (let i = 0; i < n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1]?.[t] ?? 0;
      parent[i][t] = { skip: true };

      for (let l = 0; l <= i; l++) {
        if (pal[l][i]) {
          const prev = l > 0 ? dp[l-1][t-1] : 0;
          const val = prev + (i - l + 1);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            parent[i][t] = { skip: false, l, t: t-1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n - 1, t = k;
  while (i >= 0 && t > 0) {
    const choice = parent[i][t];
    if (!choice.skip) {
      result.unshift([choice.l, i]);
      t = choice.t;
      i = choice.l - 1;
    } else {
      i--;
    }
  }

  return { maxLength: dp[n-1][k], substrings: result };
}
```

## Why This Problem Is Asked
This question evaluates understanding of dynamic programming on prefixes with a non-crossing pairing constraint. The core challenge is encoding the no-crossing condition by considering the last pair ending at position i with its left partner p.

## Key Concepts
- **DP on prefixes**: Extra dimension tracks the number of pairs formed
- **Non-crossing constraint**: Enforced by pairing i with p < i and using dp[p-1][t-1], which ensures all pairs lie completely to the left of p
- **Reconstruction**: Requires storing backpointers to output the actual pairs
- **Complexity**: Time O(n²k), Space O(nk)

## Code Example
```javascript
function maxPairs(A, k) {
  const n = A.length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(NEG));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i - 1][t];
      prev[i][t] = { skip: true };

      for (let p = 1; p < i; p++) {
        const val = dp[p - 1][t - 1] + A[p - 1] * A[i - 1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = { skip: false, p };
        }
      }
    }
  }

  const pairs = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    if (prev[i][t].skip) {
      i--;
    } else {
      const p = prev[i][t].p;
      pairs.push([p, i]);
      i = p - 1;
      t--;
    }
  }

  return { value: dp[n][k], pairs: pairs.reverse() };
}
```

## Why This Is Asked
This question introduces a new DP angle: exact k segments, per-segment cost, and sum-based values, requiring both interval DP and reconstruction.

## Key Concepts
- Prefix sums for O(1) subarray sums
- DP over i (prefix length) and t (blocks)
- Reconstructing endpoints from choice pointers

## Code Example
```javascript
function maxSumPartition(A,k,c){
  const n=A.length;
  const P=[0];
  for(const x of A) P.push(P[P.length-1]+x);
  const dp=Array.from({length:n+1},()=>Array(k+1).fill(-1e15));
  const pos=Array.from({length:n+1},()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++) dp[i][1]=(P[i]-P[0])-c, pos[i][1]=0;
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let s=t-1;s<=i-1;s++){
        const val=dp[s][t-1]+(P[i]-P[s])-c;
        if(val>dp[i][t]){ dp[i][t]=val; pos[i][t]=s; }
      }
    }
  }
  // reconstruct
  let i=n, t=k;
  const blocks=[];
  while(t>0){
    const s=pos[i][t];
    blocks.push([s, i-1]);
    i=s; t--;
  }
  blocks.reverse();
  return {score: dp[n][k], blocks};
}
```

## Why This Is Asked
This question probes DP with non-overlapping blocks and a non-additive subarray score (bitwise OR). It requires a state that handles gaps and a compact representation of OR values, plus a reconstruction strategy.

## Key Concepts
- DP over k blocks with a required gap
- Distinct ORs per end i optimization (≤ O(log MAXA))
- Backtracking pointers for block endpoints
- Time/space trade-offs and practical constants

## Code Example
```javascript
// DP sketch
for (let i=1; i<=n; i++) {
  const ors = orStates[i]; // [{val,left}, ...]
  for (let t=1; t<=k; t++) {
    for (const {val,left} of ors) {
      const prev = (left > 1) ? dp[left-2][t-1] : 0;
      dp[i][t] = Math.max(dp[i][t], prev + val);
      parent[i][t] = { left, val };
    }
  }
}
